// Run Once for All Items. Only monitor published/active workflows.
const me = String($workflow.id || '');
const items = $input.all().map(function(i) { return i.json; });
const valid = items.filter(function(w) {
  return w && w.id && w.active === true && String(w.id) !== me && !w.isArchived;
});
return valid.map(function(w) {
  return { json: { id: String(w.id), name: w.name || String(w.id) } };
});

// Run Once for All Items; one iteration = one workflow.
// This monitor uses execution history, NOT live pings to external APIs.
// OPTIONAL: Add expected runs for specific workflows (workflow ID mapped to hours).
// Examples: {'ABC123': 24, 'DEF456': 168}. A missing entry disables inactivity alerts.
const EXPECTED_RUN_EVERY_HOURS = {};
const FAILURE_WINDOW_HOURS = 24;
const REPEAT_FAILURE_THRESHOLD = 2;

const wf = $('Retrieve Workflow Details').first(0, $runIndex).json;
const now = Date.now();
const wfId = String(wf.id || '');
const name = wf.name || wfId;
const raw = $input.all().map(function(item) { return item.json; });
const executions = raw.filter(function(e) {
  return e && e.id && String(e.workflowId) === wfId;
}).sort(function(a,b) {
  return Date.parse(b.startedAt || 0) - Date.parse(a.startedAt || 0);
});
const latest = executions[0] || null;
const failures = executions.filter(function(e) {
  return ['error','crashed'].includes(String(e.status || '').toLowerCase());
});
const recentFailures = failures.filter(function(e) {
  return e.startedAt && now - Date.parse(e.startedAt) <= FAILURE_WINDOW_HOURS * 3600000;
});
const consecutiveFailures = (function() {
  let c = 0;
  for (const e of executions) {
    if (['error','crashed'].includes(String(e.status || '').toLowerCase())) c++;
    else break;
  }
  return c;
})();
const hoursSinceLast = latest && latest.startedAt
  ? Math.round((now - Date.parse(latest.startedAt))/3600000*10)/10
  : null;
const expectedHours = Number(EXPECTED_RUN_EVERY_HOURS[wfId] || 0);
const missedSla = expectedHours > 0 && (hoursSinceLast === null || hoursSinceLast > expectedHours * 1.5);
const latestFailed = Boolean(latest && ['error','crashed'].includes(String(latest.status || '').toLowerCase()));
const repeatedFailures = recentFailures.length >= REPEAT_FAILURE_THRESHOLD && consecutiveFailures > 0;
const shouldAlert = latestFailed || repeatedFailures || missedSla;

let errorNode = null;
let errorMessage = null;
const failedExecution = failures[0] || null;
if (failedExecution) {
  const d = failedExecution.data || {};
  const top = (d.resultData && d.resultData.error) || d.error || {};
  errorNode = (top.node && top.node.name) || top.nodeName || (top.node && top.node.type) || null;
  errorMessage = top.message || top.description || null;
  if (!errorNode || !errorMessage) {
    const runs = (d.resultData && d.resultData.runData) || {};
    for (const [nodeName, results] of Object.entries(runs)) {
      for (const result of (Array.isArray(results) ? results : [])) {
        if (result && result.error) {
          if (!errorNode) errorNode = nodeName;
          if (!errorMessage) errorMessage = result.error.message || result.error.description || null;
        }
      }
    }
  }
}
const clean = function(value) {
  return String(value || '')
    .replace(/(Bearer\s+)[A-Za-z0-9._-]+/gi, '$1[redacted]')
    .replace(/(api[_-]?key|access[_-]?token|secret|password)\s*[:=]\s*[^\s,;]+/gi, '$1=[redacted]')
    .slice(0,240);
};
errorMessage = errorMessage ? clean(errorMessage) : null;
const category = !errorMessage ? 'unknown' :
  /(?:^|\D)(401|403)(?:\D|$)|unauthoriz|forbidden|invalid.*token|token.*expir|credential|authenticat/i.test(errorMessage) ? 'possible_auth' :
  /(?:^|\D)429(?:\D|$)|rate.limit|too many requests/i.test(errorMessage) ? 'possible_rate_limit' :
  /timeout|ETIMEDOUT|ECONNRESET|ENOTFOUND|DNS|connection refused/i.test(errorMessage) ? 'possible_network' :
  /undefined|null|cannot read propert|unexpected token|schema/i.test(errorMessage) ? 'possible_data_shape' :
  'other';
const reason = latestFailed ? 'Last execution failed' :
  repeatedFailures ? 'Repeated recent failures' :
  missedSla ? 'Expected run is overdue' :
  !latest ? 'No saved execution history' : 'No failure detected in sampled history';
const status = shouldAlert ? 'attention' : (!latest ? 'unknown' : 'ok');
return [{ json: {
  workflowId: wfId,
  workflowName: name,
  status,
  shouldAlert,
  reason,
  latestStatus: latest ? latest.status || 'none' : 'none',
  latestExecutionId: latest ? latest.id || null : null,
  lastStartedAt: latest ? latest.startedAt || null : null,
  hoursSinceLast,
  recentFailureCount: recentFailures.length,
  consecutiveFailures,
  lastFailedExecutionId: failedExecution ? failedExecution.id || null : null,
  failedNode: errorNode,
  errorMessage,
  category,
  sampleSize: executions.length,
  expectedRunEveryHours: expectedHours || null,
  apiConnectivity: 'not_tested'
} }];

// Run Once for All Items. Loop Over Items emits all per-workflow assessments here.
const rows = $input.all().map(function(i) { return i.json; }).filter(function(v) { return v && v.workflowId; });
const alerts = rows.filter(function(r) { return r.shouldAlert; });
const unknown = rows.filter(function(r) { return r.status === 'unknown'; });
const checkedAt = new Date().toISOString();
const format = function(r) {
  let line = '- ' + r.workflowName + ' (' + r.workflowId + '): ' + r.reason;
  if (r.failedNode) line += ' | node: ' + r.failedNode;
  if (r.category && r.category !== 'unknown') line += ' | cause: ' + r.category;
  if (r.errorMessage) line += ' | error: ' + r.errorMessage;
  if (r.lastFailedExecutionId) line += ' | execution: ' + r.lastFailedExecutionId;
  return line;
};
const alertText = [
  'n8n Workflow Health Monitor - ' + checkedAt,
  'Checked: ' + rows.length + ' | Alerts: ' + alerts.length + ' | Unknown: ' + unknown.length
].concat(alerts.length ? alerts.slice(0,25).map(format) : ['No alerts.'])
 .join('\n').slice(0,3900);
return [{ json: {
  checkedAt,
  checkedCount: rows.length,
  alertCount: alerts.length,
  unknownCount: unknown.length,
  shouldAlert: alerts.length > 0,
  alertText,
  results: rows
} }];
